solution.javascript:
function extraireVoeux(lettre) {
  const voeux = [];
  let debut = -1;
  for (let i = 0; i < lettre.length; i++) {
    if (lettre[i] === "[") {
      debut = i;
    } else if (lettre[i] === "]" && debut !== -1) {
      const voeu = lettre.slice(debut + 1, i).trim().toLowerCase();
      if (voeu !== "" && !voeux.includes(voeu)) {
        voeux.push(voeu);
      }
      debut = -1;
    }
  }
  return voeux;
}

