def extraire_voeux(lettre):
    voeux = []
    debut = -1
    for i in range(len(lettre)):
        if lettre[i] == "[":
            debut = i
        elif lettre[i] == "]" and debut != -1:
            voeu = lettre[debut + 1:i].strip().lower()
            if voeu != "" and voeu not in voeux:
                voeux.append(voeu)
            debut = -1
    return voeux

