function nettoyer(texte) {
  let debut = 0;
  let fin = texte.length;
  while (debut < fin && texte[debut] === " ") {
    debut++;
  }
  while (fin > debut && texte[fin - 1] === " ") {
    fin--;
  }
  return texte.slice(debut, fin);
}

function enregistrer(fiche, cle, etat, valeur) {
  const nom = nettoyer(cle).toLowerCase();
  if (nom === "") {
    return;
  }
  if (etat === "debut") {
    fiche[nom] = "";
  } else if (etat === "libre") {
    fiche[nom] = nettoyer(valeur);
  } else if (etat === "ferme") {
    fiche[nom] = valeur;
  }
}

function lireFiche(texte) {
  const fiche = {};
  let etat = "cle";
  let cle = "";
  let valeur = "";
  let echap = false;
  for (const c of texte) {
    if (etat === "guillemets") {
      if (echap) {
        valeur += c === '"' || c === "\\" ? c : "\\" + c;
        echap = false;
      } else if (c === "\\") {
        echap = true;
      } else if (c === '"') {
        etat = "ferme";
      } else {
        valeur += c;
      }
    } else if (c === ";") {
      enregistrer(fiche, cle, etat, valeur);
      etat = "cle";
      cle = "";
      valeur = "";
    } else if (etat === "cle") {
      if (c === ":") {
        etat = "debut";
      } else {
        cle += c;
      }
    } else if (etat === "debut") {
      if (c === '"') {
        etat = "guillemets";
      } else if (c !== " ") {
        etat = "libre";
        valeur = c;
      }
    } else if (etat === "libre") {
      valeur += c;
    }
  }
  enregistrer(fiche, cle, etat, valeur);
  return fiche;
}

